-- ============================================================
-- 8 月盘点模板创建（测试库验证 SQL）
-- 依据：月盘品项_合并规格.xlsx（182 品项，单一分区「所有物料」）
-- 快照口径：名称/规格/盘点单位取 Excel（业务口径），material_id 取库行/接口 id
-- 注：4 条停用品（玫瑰杯套/防水效期贴/350ml玻璃瓶/外卖安心贴）物料行保持停用，
--     模板快照直接引用（快照机制不校验物料状态，任务创建照常复制）
-- ============================================================

-- 1) 模板（参照 7月盘点模板：type=monthly, status=1）
VALUES ('8月盘点模板', 1, 'monthly', NOW(), NOW(), 0, 'TPL202608291000000001', 1);

-- 2) 分区（单一分区，参照「盘点模板无分区」zone_name=所有物料）
VALUES (LAST_INSERT_ID(), '所有物料', 1, NOW(), 0, 'TZ202608291000000001', 0);

-- 3) 分区物料快照 182 行（sort_no 按 Excel 顺序）

-- 4) 核对
SELECT t.id, t.template_name, t.status, t.biz_code FROM template t WHERE t.template_name='8月盘点模板';
SELECT COUNT(*) AS item_cnt FROM template_zone_material tzm
JOIN template_zone tz ON tz.id = tzm.zone_id
JOIN template t ON t.id = tz.template_id WHERE t.template_name='8月盘点模板';
SELECT tzm.material_id, tzm.material_name, tzm.spec, tzm.inventory_unit, tzm.sort_no
FROM template_zone_material tzm JOIN template_zone tz ON tz.id = tzm.zone_id
JOIN template t ON t.id = tz.template_id WHERE t.template_name='8月盘点模板' ORDER BY tzm.sort_no LIMIT 5;